#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DateTime64 {
    Nat,
    Valid(i64),
}

/// Returns a Vec<bool> of the same length as `x`, where each entry is
/// true exactly when the corresponding DateTime64 is the `Nat` variant.
pub fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    x.into_iter()
     .map(|dt| matches!(dt, DateTime64::Nat))
     .collect()
}

